#include "vr_graphics.h"  // kVrGraphics[]: config/zwift-vr-graphics.txt, generated by CMake

namespace {

const wchar_t* const kProfiles[] = {L"ultra.txt", L"high.txt", L"medium.txt", L"basic.txt"};
const wchar_t kBackupSuffix[] = L".zwiftvr-backup";
const wchar_t kGpuPrefKey[] = L"Software\\Microsoft\\DirectX\\UserGpuPreferences";
const wchar_t kZwiftUninstallKey[] =
    L"SOFTWARE\\WOW6432Node\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\{E4DA422A-82AB-44A4-B3A5-0AF60F47B7AB}_is1";

std::wstring g_zwiftDir;  // with trailing backslash; empty = not known yet

void Ok(const wchar_t* fmt, ...) {
  va_list a;
  va_start(a, fmt);
  wprintf(L"  OK  ");
  vwprintf(fmt, a);
  wprintf(L"\n");
  va_end(a);
}
void Note(const wchar_t* fmt, ...) {
  va_list a;
  va_start(a, fmt);
  wprintf(L"  --  ");
  vwprintf(fmt, a);
  wprintf(L"\n");
  va_end(a);
}
void Warn(const wchar_t* fmt, ...) {
  va_list a;
  va_start(a, fmt);
  wprintf(L"  !!  ");
  vwprintf(fmt, a);
  wprintf(L"\n");
  va_end(a);
}

bool Exists(const std::wstring& p) { return GetFileAttributesW(p.c_str()) != INVALID_FILE_ATTRIBUTES; }

bool ReadAll(const std::wstring& path, std::vector<unsigned char>& out) {
  out.clear();
  HANDLE f = CreateFileW(path.c_str(), GENERIC_READ, FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE, nullptr,
                         OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL, nullptr);
  if (f == INVALID_HANDLE_VALUE) return false;
  LARGE_INTEGER size{};
  bool ok = GetFileSizeEx(f, &size) && size.QuadPart < (1 << 20);
  if (ok) {
    out.resize(static_cast<size_t>(size.QuadPart));
    DWORD got = 0;
    ok = out.empty() || (ReadFile(f, out.data(), static_cast<DWORD>(out.size()), &got, nullptr) && got == out.size());
  }
  CloseHandle(f);
  return ok;
}

bool WriteAll(const std::wstring& path, const unsigned char* data, size_t n) {
  HANDLE f = CreateFileW(path.c_str(), GENERIC_WRITE, 0, nullptr, CREATE_ALWAYS, FILE_ATTRIBUTE_NORMAL, nullptr);
  if (f == INVALID_HANDLE_VALUE) return false;
  DWORD put = 0;
  const bool ok = WriteFile(f, data, static_cast<DWORD>(n), &put, nullptr) && put == n;
  CloseHandle(f);
  return ok;
}

bool SameAsVr(const std::vector<unsigned char>& b) {
  return b.size() == sizeof(kVrGraphics) && std::equal(b.begin(), b.end(), kVrGraphics);
}

std::wstring RegString(HKEY root, const wchar_t* key, const wchar_t* value) {
  wchar_t buf[1024];
  DWORD size = sizeof(buf);
  if (RegGetValueW(root, key, value, RRF_RT_REG_SZ, nullptr, buf, &size) != ERROR_SUCCESS) return L"";
  return buf;
}

std::wstring Lower(std::wstring s) {
  for (wchar_t& c : s) c = static_cast<wchar_t>(std::towlower(c));
  return s;
}

bool ProcessRunning(const wchar_t* exe) {
  HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
  if (snap == INVALID_HANDLE_VALUE) return false;
  PROCESSENTRY32W pe{sizeof(pe)};
  bool found = false;
  for (BOOL ok = Process32FirstW(snap, &pe); ok && !found; ok = Process32NextW(snap, &pe))
    found = _wcsicmp(pe.szExeFile, exe) == 0;
  CloseHandle(snap);
  return found;
}

// Zwift's install folder with a trailing backslash, or empty if Zwift can't be found.
std::wstring ZwiftDir() {
  if (!g_zwiftDir.empty()) return g_zwiftDir;
  std::wstring d = RegString(HKEY_LOCAL_MACHINE, kZwiftUninstallKey, L"InstallLocation");
  if (!d.empty() && d.back() != L'\\') d += L'\\';
  if (!d.empty() && Exists(d + L"ZwiftApp.exe")) return d;
  wchar_t pf[MAX_PATH];
  if (GetEnvironmentVariableW(L"ProgramFiles(x86)", pf, MAX_PATH)) {
    d = std::wstring(pf) + L"\\Zwift\\";
    if (Exists(d + L"ZwiftApp.exe")) return d;
  }
  return L"";
}

// Removes the download's "Unblock" flag (the Zone.Identifier stream) from every file next to the loader.
void RemoveDownloadFlags(const std::wstring& modDir) {
  WIN32_FIND_DATAW fd;
  HANDLE h = FindFirstFileW((modDir + L"*").c_str(), &fd);
  if (h == INVALID_HANDLE_VALUE) return;
  do {
    if (!(fd.dwFileAttributes & FILE_ATTRIBUTE_DIRECTORY)) DeleteFileW((modDir + fd.cFileName + L":Zone.Identifier").c_str());
  } while (FindNextFileW(h, &fd));
  FindClose(h);
}

void SetupGraphics(const std::wstring& cfgDir, bool apply, bool quiet) {
  int installed = 0, inPlace = 0, present = 0, failed = 0;
  DWORD err = 0;
  for (const wchar_t* name : kProfiles) {
    const std::wstring target = cfgDir + name, backup = target + kBackupSuffix;
    std::vector<unsigned char> cur;
    if (!Exists(target)) continue;
    present++;
    if (!ReadAll(target, cur)) { failed++, err = GetLastError(); continue; }
    if (SameAsVr(cur)) { inPlace++; continue; }
    // Zwift's own profile (first run, or put back by a Zwift update): it becomes the backup, then the VR one goes in.
    if (!apply) { installed++; continue; }
    if (!WriteAll(backup, cur.data(), cur.size()) || !WriteAll(target, kVrGraphics, sizeof(kVrGraphics))) {
      failed++, err = GetLastError();
      continue;
    }
    installed++;
  }
  if (!present) {
    Warn(L"Zwift's graphics settings weren't found in %ls", cfgDir.c_str());
  } else if (failed) {
    Warn(L"Couldn't install the VR graphics settings into Zwift (Windows error %lu)", err);
  } else if (installed) {
    Ok(apply ? L"VR graphics settings installed into Zwift (Zwift's own kept as backups)"
             : L"VR graphics settings would be installed into Zwift (--check: nothing changed)");
  } else if (!quiet) {
    Ok(L"VR graphics settings: in place");
  }
  (void)inPlace;
}

void RestoreGraphics(const std::wstring& cfgDir, bool apply, bool quiet) {
  int restored = 0, failed = 0;
  DWORD err = 0;
  for (const wchar_t* name : kProfiles) {
    const std::wstring target = cfgDir + name, backup = target + kBackupSuffix;
    std::vector<unsigned char> cur, bak;
    if (!Exists(backup)) continue;
    if (!ReadAll(backup, bak)) { failed++, err = GetLastError(); continue; }
    if (ReadAll(target, cur) && cur == bak) continue;
    if (apply && !WriteAll(target, bak.data(), bak.size())) { failed++, err = GetLastError(); continue; }
    restored++;
  }
  if (failed) Warn(L"Couldn't put Zwift's own graphics settings back (Windows error %lu)", err);
  else if (restored) Ok(apply ? L"Zwift's own graphics settings put back" : L"Zwift's own graphics settings would be put back (--check)");
  else if (!quiet) Ok(L"Zwift's own graphics settings in use");
}

void SetupGpu(const std::wstring& zwiftExe, bool apply, bool quiet) {
  const std::wstring cur = RegString(HKEY_CURRENT_USER, kGpuPrefKey, zwiftExe.c_str());
  if (!cur.empty()) {
    if (cur.find(L"GpuPreference=2") != std::wstring::npos) {
      if (!quiet) Ok(L"Zwift runs on your high-performance graphics card");
    } else if (!quiet) {
      Note(L"Windows graphics preference for Zwift left as you set it (%ls)", cur.c_str());
    }
    return;
  }
  if (!apply) { Ok(L"Zwift would be set to your high-performance graphics card (--check)"); return; }
  const wchar_t data[] = L"GpuPreference=2;";
  const LSTATUS st = RegSetKeyValueW(HKEY_CURRENT_USER, kGpuPrefKey, zwiftExe.c_str(), REG_SZ, data, sizeof(data));
  if (st == ERROR_SUCCESS) Ok(L"Zwift set to run on your high-performance graphics card");
  else Warn(L"Couldn't set Zwift's graphics card preference (Windows error %ld)", st);
}

}  // namespace

SetupOptions ReadSetupOptions(const std::wstring& modDir) {
  const std::wstring ini = modDir + L"zwift_vr.ini";
  SetupOptions o;
  o.vrGraphics = GetPrivateProfileIntW(L"setup", L"vr_graphics", 1, ini.c_str()) != 0;
  o.gpuHighPerformance = GetPrivateProfileIntW(L"setup", L"gpu_high_performance", 1, ini.c_str()) != 0;
  return o;
}

std::wstring ProcessImagePath(DWORD pid) {
  HANDLE p = OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION, FALSE, pid);
  if (!p) return L"";
  wchar_t buf[MAX_PATH];
  DWORD n = MAX_PATH;
  const bool ok = QueryFullProcessImageNameW(p, 0, buf, &n);
  CloseHandle(p);
  return ok ? std::wstring(buf, n) : L"";
}

void SetZwiftExe(const std::wstring& exePath) {
  const size_t slash = exePath.find_last_of(L"\\/");
  if (slash != std::wstring::npos) g_zwiftDir = exePath.substr(0, slash + 1);
}

void RunSetup(const std::wstring& modDir, const SetupOptions& o, bool zwiftRunning, bool apply, bool quiet) {
  if (apply) RemoveDownloadFlags(modDir);
  const std::wstring zdir = ZwiftDir();
  if (zdir.empty()) {
    Warn(L"Zwift wasn't found - the graphics setup runs once Zwift has started");
    return;
  }
  if (zwiftRunning) {
    if (!quiet) Note(L"Zwift is running: its graphics settings are checked again after it closes");
  } else if (o.vrGraphics) {
    SetupGraphics(zdir + L"data\\configs\\", apply, quiet);
  } else {
    RestoreGraphics(zdir + L"data\\configs\\", apply, quiet);
  }
  if (o.gpuHighPerformance) SetupGpu(zdir + L"ZwiftApp.exe", apply, quiet);
}

void CheckHeadset(bool quiet) {
  const std::wstring rt = RegString(HKEY_LOCAL_MACHINE, L"SOFTWARE\\Khronos\\OpenXR\\1", L"ActiveRuntime");
  const std::wstring l = Lower(rt);
  const wchar_t* name = l.find(L"oculus") != std::wstring::npos          ? L"Meta Horizon Link"
                        : l.find(L"steamvr") != std::wstring::npos       ? L"SteamVR"
                        : l.find(L"pimax") != std::wstring::npos         ? L"Pimax"
                        : l.find(L"virtualdesktop") != std::wstring::npos ? L"Virtual Desktop"
                        : l.find(L"mixedreality") != std::wstring::npos  ? L"Windows Mixed Reality"
                                                                         : nullptr;
  const bool metaInstalled = !RegString(HKEY_LOCAL_MACHINE,
                                        L"SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\Oculus",
                                        L"InstallLocation").empty();
  const bool meta = l.find(L"oculus") != std::wstring::npos;
  if (rt.empty()) {
    Warn(L"No headset runtime is set. Quest: in Meta Horizon Link, Settings > General > OpenXR Runtime > Set Meta "
         L"Horizon Link as active");
    return;
  }
  if (!quiet) {
    if (name) Ok(L"Headset runtime: %ls", name);
    else Ok(L"Headset runtime: %ls", rt.c_str());
  }
  if (!meta && metaInstalled && !quiet)
    Note(L"Using a Quest? In Meta Horizon Link: Settings > General > OpenXR Runtime > Set Meta Horizon Link as active");
  if (meta && !ProcessRunning(L"OVRServer_x64.exe"))
    Warn(L"Meta Horizon Link isn't running: start it and connect your headset before Zwift");
}

bool RestoreZwiftGraphics(bool zwiftRunning) {
  const std::wstring zdir = ZwiftDir();
  if (zdir.empty()) { Warn(L"Zwift wasn't found"); return false; }
  if (zwiftRunning) { Warn(L"Close Zwift first, then run this again"); return false; }
  const std::wstring cfg = zdir + L"data\\configs\\";
  bool any = false;
  for (const wchar_t* name : kProfiles) any = any || Exists(cfg + name + kBackupSuffix);
  if (!any) { Note(L"No backups found: Zwift's graphics settings were never changed by the mod"); return false; }
  RestoreGraphics(cfg, true, false);
  Note(L"To keep Zwift's own settings while using the mod, set vr_graphics = 0 in zwift_vr.ini");
  return true;
}
